function Show-Help {
    Write-Host '
Esse script foi escrito por Vinicius ''N00TROPx1C'' Mello.

Apelidado de N00-FOR.ps1, esse script foi escrito para ser executado de uma mídia removível
ou copiado e executado diretamente no console do powershell, a fim de evitar possíveis erros
de permissão. Cansado de chegar em incidente e se deparar com os mais diversos tipos de
servidores windows mal configurados, decidi unificar as coletas mais relevantes em um único script.

OPÇÃO 1 (Full):
Busca todos os arquivos/evidências com relevância forense, incluindo o uso do Magnet RAM Capture
para um dump de RAM (arquivo .mem fica FORA do zip — envie por canal próprio), cálculo de hashes
de tarefas agendadas e de processos com conexão ativa, e varredura Hollows Hunter (minidumps).

OPÇÃO 2 (Fast):
Busca pelos arquivos principais com mais relevância, a fim de minimizar o tempo.
Evita processos demorados, caso você já tenha feito dump de RAM anteriormente.

OPÇÃO 3 finaliza o script, assim como um ctrl+c.

Este script foca em coletas de dados voláteis e não voláteis, e deve ser executado de uma
mídia EXTERNA ao servidor (pendrive/HD externo). Um dump de disco completo pode ser
EXTREMAMENTE demorado — este script cobre o essencial para iniciar a análise enquanto
a imagem bit a bit roda em paralelo.

SAÍDA:
  <destino>\N00-FOR_<HOST>_<data>\evidence\...  (artefatos + manifest.json)
  <destino>\N00-FOR_<HOST>_<data>\RAM\...       (dump de memória, fora do zip)
  <destino>\N00-FOR_<HOST>_<data>.zip           (envie este ao analista)
  <destino>\N00-FOR_<HOST>_<data>.zip.sha256    (verificação de integridade)
' -BackgroundColor Black -ForegroundColor Red
}

# =============================================================================
# VERIFICAÇÃO DE PRIVILÉGIOS (elevação automática)
# =============================================================================

$isAdmin = ([Security.Principal.WindowsPrincipal] [Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Host 'Este script precisa ser executado com privilégios administrativos.' -ForegroundColor Red
    Write-Host 'Reiniciando em modo administrativo...' -ForegroundColor Red -BackgroundColor Black
    Start-Sleep -Seconds 2

    # Preserva os parâmetros passados na linha de comando ao re-elevar
    $argList = @()
    foreach ($key in $PSBoundParameters.Keys) {
        $val = $PSBoundParameters[$key]
        if ($val -is [switch]) {
            if ($val) { $argList += "-$key" }
        }
        elseif ($key -eq 'Mode') {
            $argList += "-Mode $val"
        }
        elseif ($key -eq 'Out') {
            $argList += "-Out `"$val`""
        }
    }
    $scriptPath = $PSCommandPath
    if (-not $scriptPath) { $scriptPath = $MyInvocation.MyCommand.Path }
    Start-Process powershell.exe -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`" $($argList -join ' ')" -Verb RunAs
    exit
}

# =============================================================================
# FLUXO PRINCIPAL
# =============================================================================

# Seleção do modo: CLI tem prioridade; sem CLI, exibe menu interativo
if (-not $Mode) {
    Show-Banner
    while ($true) {
        $choice = Read-Host 'Digite o número da opção desejada'
        switch ($choice) {
            '1' { $Mode = 'Full'; break }
            '2' { $Mode = 'Fast'; break }
            '3' { exit }
            '4' { Show-Help; continue }
            default { Write-Warn-Script 'Opção inválida. Tente novamente.'; continue }
        }
        break
    }
}
else {
    Show-Banner
}

# Estrutura de saída
$hostname = $env:COMPUTERNAME
$stamp   = Get-Date -Format 'yyyyMMdd-HHmmss'
$destBase = Join-Path $Out "N00-FOR_${hostname}_$stamp"
$evidenceDir = Join-Path $destBase 'evidence'
$ramDir      = Join-Path $destBase 'RAM'

$dirs = @(
    $destBase,
    $evidenceDir,
    $ramDir,
    (Join-Path $evidenceDir 'system'),
    (Join-Path $evidenceDir 'network'),
    (Join-Path $evidenceDir 'users'),
    (Join-Path $evidenceDir 'persistence'),
    (Join-Path $evidenceDir 'evtx'),
    (Join-Path $evidenceDir 'amcache'),
    (Join-Path $evidenceDir 'hunter')
)
foreach ($d in $dirs) { New-Item -Path $d -ItemType Directory -Force | Out-Null }

# Verificação de espaço em disco
$freeDest = Get-FreeSpaceGB -Path $destBase
if ($freeDest -ge 0 -and $freeDest -lt 5) {
    Write-Warn-Script "Atenção: apenas $freeDest GB livres no volume de destino. Dump de RAM pode falhar."
}

# Transcript: log de execução completo (fora do zip)
$runLog = Join-Path $destBase 'N00-FOR_run.log'
try {
    Start-Transcript -Path $runLog -Force -ErrorAction Stop
}
catch {
    Write-Warn-Script "Não foi possível iniciar o transcript: $($_.Exception.Message)"
}

Write-Host ''
Write-Info "Modo de coleta : $Mode"
Write-Info "Hostname       : $hostname"
Write-Info "Destino        : $destBase"
Write-Info "N00-FOR        : v$($script:Version)"
Write-Host ''

try {
    # -------------------------------------------------------------------------
    # 1. RAM (ordem de volatilidade: memória primeiro)
    # -------------------------------------------------------------------------
    if ($Mode -eq 'Full' -and -not $NoRam) {
        Invoke-RamDump -RamDir $ramDir
    }
    elseif ($Mode -eq 'Full') {
        Write-Info 'Dump de RAM pulado (-NoRam).'
    }
    else {
        Write-Info 'Dump de RAM pulado (modo Fast).'
    }

    # -------------------------------------------------------------------------
    # 2. Coletas de sistema e rede
    # -------------------------------------------------------------------------
    Collect-SystemInfo       -Dir (Join-Path $evidenceDir 'system')
    Collect-Processes        -Dir (Join-Path $evidenceDir 'system')
    Collect-Services         -Dir (Join-Path $evidenceDir 'system')
    Collect-Disks            -Dir (Join-Path $evidenceDir 'system')
    Collect-Hotfixes         -Dir (Join-Path $evidenceDir 'system')
    Collect-NetAdapters      -Dir (Join-Path $evidenceDir 'system')

    Collect-NetworkTcp       -Dir (Join-Path $evidenceDir 'network')
    Collect-DnsCache         -Dir (Join-Path $evidenceDir 'network')
    Collect-SmbShares        -Dir (Join-Path $evidenceDir 'network')

    Collect-LocalUsers       -Dir (Join-Path $evidenceDir 'users')
    Collect-PsHistory        -UsersDir (Join-Path $evidenceDir 'users')

    # -------------------------------------------------------------------------
    # 3. Persistência e execução
    # -------------------------------------------------------------------------
    Collect-Autoruns         -Dir (Join-Path $evidenceDir 'persistence')
    Collect-ScheduledTasks   -Dir (Join-Path $evidenceDir 'persistence')

    # -------------------------------------------------------------------------
    # 4. Logs e bancos de execução
    # -------------------------------------------------------------------------
    Collect-Evtx             -Dir (Join-Path $evidenceDir 'evtx')
    Collect-Amcache          -Dir (Join-Path $evidenceDir 'amcache')

    # -------------------------------------------------------------------------
    # 5. Etapas do modo Full
    # -------------------------------------------------------------------------
    if ($Mode -eq 'Full') {
        Collect-ScheduledTaskHashes   -Dir (Join-Path $evidenceDir 'persistence')
        Collect-ListeningProcessHashes -Dir (Join-Path $evidenceDir 'network')
        Invoke-HollowsHunter          -Dir (Join-Path $evidenceDir 'hunter')
    }

    # -------------------------------------------------------------------------
    # 6. Manifest e ZIP
    # -------------------------------------------------------------------------
    New-Manifest -EvidenceDir $evidenceDir -CollectionMode $Mode

    if (-not $NoZip) {
        $zipPath = "$destBase.zip"
        $zipHash = New-CollectionZip -EvidenceDir $evidenceDir -ZipPath $zipPath
    }

    Write-Host ''
    Write-Step 'COLETA CONCLUÍDA'
    Write-Info "Pasta de evidências : $evidenceDir"
    if ($Mode -eq 'Full' -and -not $NoRam) {
        Write-Info "Dump de RAM         : $ramDir (fora do zip — envie por canal seguro)"
    }
    if (-not $NoZip) {
        Write-Info "ZIP                 : $destBase.zip"
        Write-Info "SHA256 do ZIP       : $zipHash"
        Write-Info 'Envie o arquivo .zip ao analista. Guarde o .sha256 para conferência de integridade.'
    }
    else {
        Write-Info 'ZIP não gerado (-NoZip). Envie a pasta de evidências por canal seguro.'
    }
    Write-Host ''
}
catch {
    Write-Host "ERRO FATAL: $($_.Exception.Message)" -ForegroundColor Red -BackgroundColor Black
    Write-Host "Linha: $($_.InvocationInfo.ScriptLineNumber)" -ForegroundColor Red
    Write-Warn-Script 'A coleta terminou com erro. Verifique o log de execução na pasta de saída.'
}
finally {
    # Transcript pode não estar ativo (ex: falha no Start-Transcript) — erro ignorado
    try { Stop-Transcript | Out-Null } catch { }
}
